/// Check and apply the answer to a pending task. Returns warnings; a rejected answer is an
/// error listing what to fix, and the task stays pending. Each submit is recorded in the
/// run log, with the coverage of a planning answer's quotes.
pub fn submit(project: &Project, id: &str) -> Result<Vec<String>> {
    use crate::runlog::{Outcome, What};
    let _lock = Lock::acquire(project)?;
    let task = load_state(project)?
        .pending
        .into_iter()
        .find(|t| t.id == id);
    let coverage = task.as_ref().and_then(|t| planning_coverage(project, t));
    let events = crate::runlog::load(project);
    // With `[checks] coverage = "reject"`, an answer drawn from part of the sources goes
    // back, at most `coverage_retries` times; after that it is accepted with a warning.
    // A pilot's argument explains part of the target, so it may leave sections unquoted.
    let pilot_argument = matches!(task.as_ref().map(|t| &t.kind), Some(Kind::Argument))
        && project.load_graph()?.is_some_and(|g| g.pilot.is_some());
    let shortfall = coverage
        .as_deref()
        .filter(|_| !pilot_argument)
        .and_then(|c| {
            let results =
                project.config.checks.coverage_depth == crate::config::CoverageDepth::Results;
            crate::coverage::rejection(c, &project.sources, results)
        });
    let rejecting = project.config.checks.coverage == crate::config::CoverageCheck::Reject;
    let sent_back = crate::runlog::coverage_rejections(&events, id);
    let gate = shortfall
        .clone()
        .filter(|_| rejecting && sent_back < project.config.checks.coverage_retries as usize);
    let result = submit_locked(project, id, gate.as_deref()).map(|mut warnings| {
        if rejecting && gate.is_none() && shortfall.is_some() {
            warnings.push(format!(
                "accepted after {sent_back} rejections for coverage, with most of the sections \
                 that develop results still unquoted (see `exegenius status`)"
            ));
        }
        warnings
    });
    let check = match (&result, &gate) {
        (Err(Error::Invalid(m)), Some(g)) if m == g => Some("coverage".to_string()),
        _ => None,
    };
    let (outcome, message, warnings) = match &result {
        Ok(warnings) => (Outcome::Accepted, None, warnings.clone()),
        // Checked and rejected, as opposed to not checked: no answer file, or not pending.
        Err(e @ Error::Invalid(m)) if task.is_some() && !m.starts_with("no answer yet") => {
            (Outcome::Rejected, Some(e.to_string()), Vec::new())
        }
        Err(e) => (Outcome::Error, Some(e.to_string()), Vec::new()),
    };
    let attempt = crate::runlog::submits(&events, id) + 1;
    crate::runlog::append(
        project,
        What::Submit {
            task: id.to_string(),
            kind: task.as_ref().map(|t| t.label().to_string()),
            attempt,
            outcome,
            message,
            warnings,
            check,
            coverage,
        },
    );
    result
}

/// For an extract or argument task whose answer file parses: where the answer's quotes
/// fall in the sources.
fn planning_coverage(project: &Project, task: &Task) -> Option<Vec<crate::coverage::Coverage>> {
    use crate::coverage::{argument_owners, concept_owners, coverage};
    let text = std::fs::read_to_string(project.root.join(task.answer())).ok()?;
    match task.kind {
        Kind::Extract => {
            let answer: ExtractAnswer = serde_json::from_str(&text).ok()?;
            Some(coverage(
                &project.sources,
                &concept_owners(&answer.concepts),
            ))
        }
        Kind::Argument => {
            let answer: ArgumentAnswer = serde_json::from_str(&text).ok()?;
            let graph = project.load_graph().ok().flatten();
            Some(coverage(
                &project.sources,
                &argument_owners(&answer.root, graph.as_ref()),
            ))
        }
        _ => None,
    }
}

/// [`submit`], under the lock. `gate` is the rejection to give an extract or argument answer
/// that passes its other checks.
fn submit_locked(project: &Project, id: &str, gate: Option<&str>) -> Result<Vec<String>> {
    let mut state = load_state(project)?;
    let Some(index) = state.pending.iter().position(|t| t.id == id) else {
        return Err(Error::Invalid(format!(
            "`{id}` is not a pending task (run `exegenius next` to see the pending tasks)"
        )));
    };
    let task = state.pending[index].clone();
    let path = project.root.join(task.answer());
    if !path.exists() {
        return Err(Error::Invalid(format!(
            "no answer yet: write it to {}",
            task.answer().display()
        )));
    }
    let text = read(&path)?;
    let graph = project.load_graph()?;
    let warnings = match &task.kind {
        Kind::Extract => {
            let (graph, warnings) = apply_extract(project, parse(&path, &text)?)?;
            if let Some(gate) = gate {
                return Err(Error::Invalid(gate.to_string()));
            }
            project.save_graph(&graph)?;
            warnings
        }
        Kind::Background => {
            let mut graph = require(graph)?;
            apply_background(&mut graph, parse(&path, &text)?)?;
            project.save_graph(&graph)?;
            Vec::new()
        }
        Kind::Extend => {
            let mut graph = require(graph)?;
            let limit = crate::extract::new_pages(&crate::audit::load_rounds(project)?);
            let warnings = apply_extend(project, &mut graph, parse(&path, &text)?, limit)?;
            project.save_graph(&graph)?;
            warnings
        }
        Kind::Argument => {
            let graph = require(graph)?;
            let plan = plan(&graph, &project.sources)?;
            let answer: ArgumentAnswer = parse(&path, &text)?;
            if let Some(gate) = gate {
                crate::argument::validate(project, &graph, &plan, &answer)?;
                return Err(Error::Invalid(gate.to_string()));
            }
            apply_argument(project, &graph, &plan, answer)?
        }
        Kind::Write { page } => {
            let mut graph = require(graph)?;
            let plan = plan(&graph, &project.sources)?;
            find_page(&plan, page)?;
            let fields_path = project
                .root
                .join(task.fields().expect("write tasks have a fields file"));

